import React, { useState, useEffect, useRef, useCallback } from 'react';
import { BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, Tooltip, ResponsiveContainer, LineChart, Line, CartesianGrid } from 'recharts';
import { api } from './utils/api';
const r = await api.createClient({ ...form, balance: parseFloat(form.balance) || 0 });
// ─── Styles ─────────────────────────────────────────────────────────────────
const css = `
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg:       #080c14;
    --surface:  #0f1724;
    --surface2: #162035;
    --border:   #1e2d4a;
    --accent:   #3b82f6;
    --accent2:  #06b6d4;
    --green:    #10b981;
    --red:      #ef4444;
    --amber:    #f59e0b;
    --purple:   #8b5cf6;
    --text:     #e2e8f0;
    --muted:    #64748b;
    --mono:     'JetBrains Mono', monospace;
    --sans:     'Space Grotesk', sans-serif;
  }

  body { font-family: var(--sans); background: var(--bg); color: var(--text); }

  .app { display: flex; min-height: 100vh; }

  /* Sidebar */
  .sidebar {
    width: 220px; min-height: 100vh; background: var(--surface);
    border-right: 1px solid var(--border); padding: 24px 0; flex-shrink: 0;
    display: flex; flex-direction: column;
  }
  .logo {
    padding: 0 20px 24px; font-size: 18px; font-weight: 700; color: var(--accent);
    border-bottom: 1px solid var(--border); letter-spacing: -0.5px;
  }
  .logo span { color: var(--accent2); }
  .nav { flex: 1; padding-top: 16px; }
  .nav-item {
    display: flex; align-items: center; gap: 12px; padding: 11px 20px;
    cursor: pointer; font-size: 14px; font-weight: 500; color: var(--muted);
    transition: all 0.15s; border-left: 3px solid transparent;
  }
  .nav-item:hover { color: var(--text); background: var(--surface2); }
  .nav-item.active { color: var(--accent); border-left-color: var(--accent); background: rgba(59,130,246,0.08); }
  .nav-icon { font-size: 16px; width: 20px; text-align: center; }

  /* Main */
  .main { flex: 1; overflow-y: auto; padding: 28px 32px; }
  .page-title { font-size: 22px; font-weight: 700; margin-bottom: 24px; letter-spacing: -0.3px; }
  .page-title span { color: var(--muted); font-size: 14px; font-weight: 400; margin-left: 12px; }

  /* Grid */
  .grid { display: grid; gap: 16px; }
  .grid-4 { grid-template-columns: repeat(4, 1fr); }
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .grid-2 { grid-template-columns: 1fr 1fr; }

  /* Cards */
  .card {
    background: var(--surface); border: 1px solid var(--border);
    border-radius: 12px; padding: 20px;
  }
  .card-title { font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.8px; margin-bottom: 12px; }
  .card-value { font-size: 32px; font-weight: 700; letter-spacing: -1px; }
  .card-sub { font-size: 12px; color: var(--muted); margin-top: 4px; }

  /* Stat cards */
  .stat-card { position: relative; overflow: hidden; }
  .stat-card::after {
    content: ''; position: absolute; top: -20px; right: -20px;
    width: 80px; height: 80px; border-radius: 50%;
    background: rgba(255,255,255,0.03);
  }

  /* Node cards */
  .nodes-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 20px; }
  .node-card {
    background: var(--surface); border: 1px solid var(--border);
    border-radius: 10px; padding: 16px; position: relative;
  }
  .node-card.master { border-color: var(--accent); }
