  .node-card.offline { border-left: 3px solid var(--red); opacity: 0.7; }
  .node-badge {
    display: inline-block; padding: 2px 8px; border-radius: 20px;
    font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;
  }
  .badge-master { background: rgba(59,130,246,0.15); color: var(--accent); }
  .badge-slave  { background: rgba(16,185,129,0.15); color: var(--green); }
  .badge-online { background: rgba(16,185,129,0.15); color: var(--green); }
  .badge-offline{ background: rgba(239,68,68,0.15);  color: var(--red); }
  .badge-go     { background: rgba(6,182,212,0.15);  color: var(--accent2); }
  .badge-python { background: rgba(245,158,11,0.15); color: var(--amber); }
