  .data-table tr:hover td { background: rgba(255,255,255,0.02); }

  /* Log */
  .log-line { font-family: var(--mono); font-size: 12px; padding: 5px 0; border-bottom: 1px solid rgba(30,45,74,0.4); display: flex; gap: 10px; }
  .log-time { color: var(--muted); flex-shrink: 0; }
  .log-ok    { color: var(--green); }
  .log-err   { color: var(--red); }
  .log-info  { color: var(--accent2); }

  /* AI box */
  .ai-input-wrap { display: flex; gap: 10px; margin-bottom: 14px; }
  .ai-input {
    flex: 1; background: var(--surface2); border: 1px solid var(--border);
