    cursor: pointer; font-weight: 600; font-size: 14px; transition: opacity 0.15s;
  }
  .ai-btn:hover { opacity: 0.9; }
  .ai-btn:disabled { opacity: 0.4; cursor: not-allowed; }
  .sql-preview {
    background: #000913; border: 1px solid var(--border); border-radius: 8px;
