  .election-card { padding: 20px; border-radius: 10px; border: 1px solid var(--border); background: var(--surface); margin-bottom: 14px; }
  .leader-name { font-size: 28px; font-weight: 700; color: var(--accent); letter-spacing: -0.5px; }
  .term-badge { background: rgba(59,130,246,0.15); color: var(--accent); padding: 4px 12px; border-radius: 20px; font-size: 12px; font-weight: 600; }
  .danger-btn {
    background: rgba(239,68,68,0.15); color: var(--red); border: 1px solid rgba(239,68,68,0.3);
