`;

// ─── Colors ─────────────────────────────────────────────────────────────────
const CITY_COLORS = { Cairo: '#3b82f6', Alexandria: '#06b6d4', Assiut: '#10b981', Luxor: '#f59e0b' };
const PIE_COLORS = ['#3b82f6', '#06b6d4', '#10b981', '#f59e0b', '#8b5cf6', '#ef4444'];
const LANG_BADGES = { 'worker-1': 'go', 'worker-2': 'python', 'worker-3': 'nodejs', 'master-1': 'go' };

// ─── Helpers ─────────────────────────────────────────────────────────────────
const fmt = n => n != null ? parseFloat(n).toLocaleString(undefined, { maximumFractionDigits: 0 }) : '—';
const fmtE = n => n != null ? parseFloat(n).toExponential(2) : '—';
const fmtB = n => n != null ? `${parseFloat(n).toFixed(1)}%` : '—';
const ts = () => new Date().toLocaleTimeString();

// ─── Nav items ───────────────────────────────────────────────────────────────
const NAV = [
  { key: 'overview', label: 'Overview', icon: '⬡' },
  { key: 'cluster', label: 'Cluster', icon: '◈' },
  { key: 'query', label: 'SQL Terminal', icon: '❯' },
  { key: 'ai', label: 'AI Query', icon: '✦' },
  { key: 'data', label: 'Data Browser', icon: '⊡' },
  { key: 'replication', label: 'Replication', icon: '⇄' },
  { key: 'election', label: 'Leader Election', icon: '♛' },
];

// ─── App ─────────────────────────────────────────────────────────────────────
export default function App() {
  const [page, setPage] = useState('overview');
  const [stats, setStats] = useState(null);
  const [nodes, setNodes] = useState([]);
  const [health, setHealth] = useState({});
  const [shards, setShards] = useState([]);

  // Polling
  const poll = useCallback(async () => {
    try {
      const [s, n, h, sh] = await Promise.allSettled([
        api.getStats(), api.clusterNodes(), api.clusterHealth(), api.clusterShards()
      ]);
      if (s.status === 'fulfilled') setStats(s.value);
      if (n.status === 'fulfilled') setNodes(n.value?.nodes || []);
      if (h.status === 'fulfilled') setHealth(h.value || {});
      if (sh.status === 'fulfilled') setShards(sh.value?.shards || []);
    } catch { }
  }, []);

  useEffect(() => {
    poll();
    const id = setInterval(poll, 5000);
    return () => clearInterval(id);
  }, [poll]);

  return (
    <>
      <style>{css}</style>
      <div className="app">
        <aside className="sidebar">
          <div className="logo">Distrib<span>DB</span></div>
          <nav className="nav">
            {NAV.map(n => (
              <div key={n.key} className={`nav-item ${page === n.key ? 'active' : ''}`} onClick={() => setPage(n.key)}>
                <span className="nav-icon">{n.icon}</span>
                {n.label}
              </div>
            ))}
          </nav>
          <div style={{ padding: '16px 20px', borderTop: '1px solid var(--border)' }}>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>GO · PYTHON · NODE.JS</div>
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 2 }}>4-Node Cluster</div>
          </div>
        </aside>

        <main className="main">
          {page === 'overview' && <Overview stats={stats} nodes={nodes} shards={shards} />}
          {page === 'cluster' && <Cluster nodes={nodes} health={health} />}
          {page === 'query' && <QueryTerminal />}
          {page === 'ai' && <AIQuery />}
          {page === 'data' && <DataBrowser />}
          {page === 'replication' && <ReplicationView />}
          {page === 'election' && <ElectionView />}
        </main>
      </div>
    </>
  );
}

// ─── Overview ────────────────────────────────────────────────────────────────
function Overview({ stats, nodes, shards }) {
  const total = stats?.total_clients ?? '—';
  const balance = stats?.total_balance ?? null;
  const cityRows = stats?.by_city?.rows || [];
  const typeRows = stats?.by_account_type?.rows || [];

  const cityData = cityRows.map(r => ({ name: r[0], clients: r[1], balance: parseFloat(r[2]) }));
  const typeData = typeRows.map(r => ({ name: r[0], value: r[1] }));

  const onlineCount = nodes.filter(n => (n.live_status || n.status) === 'online').length;

  return (
    <>
      <div className="page-title">Overview <span>Distributed Database System</span></div>

      <div className="grid grid-4 mb16">
        <StatCard title="Total Clients" value={fmt(total)} sub="Across all shards" color="var(--accent)" icon="👥" />
        <StatCard title="Total Balance" value={balance ? `$${(balance / 1e6).toFixed(1)}M` : '—'} sub="Combined portfolio" color="var(--green)" icon="💰" />
        <StatCard title="Active Nodes" value={`${onlineCount}/4`} sub="Master + 3 workers" color="var(--accent2)" icon="◈" />
        <StatCard title="Shard Count" value={shards.length || 4} sub="City partitions" color="var(--purple)" icon="⬡" />
      </div>

      <div className="grid grid-2 mb16">
        <div className="card">
          <div className="card-title">Clients by City (Shard)</div>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={cityData} margin={{ left: -20 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
              <XAxis dataKey="name" tick={{ fill: '#64748b', fontSize: 12 }} />
              <YAxis tick={{ fill: '#64748b', fontSize: 12 }} />
              <Tooltip contentStyle={{ background: '#0f1724', border: '1px solid #1e2d4a', borderRadius: 8, color: '#e2e8f0' }} />
              <Bar dataKey="clients" radius={[4, 4, 0, 0]}>
                {cityData.map((d, i) => <Cell key={i} fill={CITY_COLORS[d.name] || '#3b82f6'} />)}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="card">
          <div className="card-title">Account Type Distribution</div>
          <ResponsiveContainer width="100%" height={200}>
            <PieChart>
              <Pie data={typeData} cx="50%" cy="50%" outerRadius={80} dataKey="value" label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`} labelLine={false}>
                {typeData.map((_, i) => <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
              </Pie>
              <Tooltip contentStyle={{ background: '#0f1724', border: '1px solid #1e2d4a', borderRadius: 8 }} />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="card">
        <div className="card-title">Shard Distribution</div>
        {shards.length === 0 ? <div className="empty">Loading shard data...</div> :
          shards.map(s => {
            const maxRows = Math.max(...shards.map(x => x.row_count));
            const pct = (s.row_count / maxRows) * 100;
            return (
              <div key={s.city} className="shard-item">
                <div className="shard-city">{s.city}</div>
                <div style={{ fontSize: 11, color: 'var(--muted)', width: 80 }}>{s.node_id}</div>
                <div className="shard-bar"><div className="shard-fill" style={{ width: `${pct}%`, background: CITY_COLORS[s.city] }} /></div>
                <div className="shard-count">{fmt(s.row_count)}</div>
              </div>
            );
          })
        }
      </div>
    </>
  );
}

function StatCard({ title, value, sub, color, icon }) {
  return (
    <div className="card stat-card">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div>
          <div className="card-title">{title}</div>
          <div className="card-value" style={{ color }}>{value}</div>
          <div className="card-sub">{sub}</div>
        </div>
        <div style={{ fontSize: 28, opacity: 0.5 }}>{icon}</div>
      </div>
    </div>
  );
}

// ─── Cluster ──────────────────────────────────────────────────────────────────
function Cluster({ nodes, health }) {
  const enriched = nodes.map(n => ({
    ...n,
    ...(health[n.node_id] || {}),
    live_status: health[n.node_id]?.status || n.status || 'unknown'
  }));

  return (
    <>
      <div className="page-title">Cluster Monitor <span>Real-time node health</span></div>
      <div className="nodes-grid">
        {enriched.map(n => <NodeCard key={n.node_id} node={n} />)}
      </div>
    </>
  );
}

function NodeCard({ node }) {
  const online = node.live_status === 'online';
  const isMaster = node.role === 'master';
  const lang = LANG_BADGES[node.node_id] || 'go';

  return (
    <div className={`node-card ${isMaster ? 'master' : ''} ${online ? 'online' : 'offline'}`}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
        <span className={`node-badge ${isMaster ? 'badge-master' : 'badge-slave'}`}>
          {isMaster ? 'MASTER' : 'SLAVE'}
        </span>
        <span className={`node-badge badge-${lang}`}>{lang.toUpperCase()}</span>
      </div>
      <div style={{ fontWeight: 700, marginBottom: 4 }}>{node.node_id}</div>
      <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 12 }}>
        {node.shard || 'All shards'}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: 10 }}>
        <span className={`pulse ${online ? 'green' : 'red'}`} />
        <span style={{ fontSize: 12, fontWeight: 600, color: online ? 'var(--green)' : 'var(--red)' }}>
          {online ? 'ONLINE' : 'OFFLINE'}
        </span>
        {node.latency_ms != null && <span style={{ fontSize: 11, color: 'var(--muted)', marginLeft: 'auto' }}>{node.latency_ms}ms</span>}
      </div>
      <div style={{ fontSize: 11, color: 'var(--muted)', marginBottom: 2 }}>CPU {fmtB(node.cpu)}</div>
      <div className="meter"><div className="meter-fill cpu" style={{ width: `${Math.min(100, node.cpu || 0)}%` }} /></div>
      <div style={{ fontSize: 11, color: 'var(--muted)', marginBottom: 2, marginTop: 8 }}>RAM {fmtB(node.ram)}</div>
      <div className="meter"><div className="meter-fill ram" style={{ width: `${Math.min(100, node.ram || 0)}%` }} /></div>
    </div>
  );
}

// ─── SQL Terminal ─────────────────────────────────────────────────────────────
function QueryTerminal() {
  const [sql, setSql] = useState('SELECT id, name, city, account_type, balance FROM client LIMIT 10');
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [logs, setLogs] = useState([]);

  const run = async () => {
    if (!sql.trim()) return;
    setLoading(true); setError('');
    addLog(sql, 'info');
    try {
      const r = await api.query(sql);
      if (r.error) { setError(r.error); setResult(null); addLog(r.error, 'err'); }
      else { setResult(r); addLog(`${r.rows?.length ?? r.affected ?? 0} row(s) — ${r.duration}`, 'ok'); }
    } catch (e) { setError(e.message); addLog(e.message, 'err'); }
    setLoading(false);
  };

  const addLog = (msg, type) => setLogs(l => [...l.slice(-50), { msg, type, time: ts() }]);

  const examples = [
    'SELECT * FROM client WHERE city = \'Cairo\' LIMIT 20',
    'SELECT city, COUNT(*), AVG(balance) FROM client GROUP BY city',
    'SELECT gender, COUNT(*) FROM client GROUP BY gender',
    'SELECT * FROM client ORDER BY balance DESC LIMIT 5',
  ];

  return (
    <>
      <div className="page-title">SQL Terminal <span>Master node query executor</span></div>
      <div style={{ display: 'flex', gap: 6, marginBottom: 12, flexWrap: 'wrap' }}>
        {examples.map((e, i) => (
          <button key={i} onClick={() => setSql(e)} style={{ background: 'var(--surface2)', border: '1px solid var(--border)', color: 'var(--muted)', padding: '4px 10px', borderRadius: 5, cursor: 'pointer', fontSize: 11 }}>
            Example {i + 1}
          </button>
        ))}
      </div>
      <div className="terminal mb16">
        <div className="terminal-header"><div className="dot dot-red" /><div className="dot dot-amber" /><div className="dot dot-green" /><span style={{ fontSize: 11, color: 'var(--muted)', marginLeft: 8 }}>master@distributed-db</span></div>
        <div className="terminal-input">
          <span className="prompt">sql❯</span>
          <input value={sql} onChange={e => setSql(e.target.value)} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && run()} placeholder="Enter SQL query..." />
          <button className="run-btn" onClick={run} disabled={loading}>{loading ? '...' : 'RUN'}</button>
        </div>
        <div className="terminal-output">
          {logs.map((l, i) => (
            <div key={i} className="log-line">
              <span className="log-time">[{l.time}]</span>
              <span className={`log-${l.type}`}>{l.msg}</span>
            </div>
          ))}
        </div>
      </div>

      {error && <div className="error mb16">⚠ {error}</div>}

      {result && (
        <div className="card">
          <div className="card-title" style={{ display: 'flex', justifyContent: 'space-between' }}>
            <span>Result — {result.rows?.length ?? 0} rows</span>
            <span style={{ color: 'var(--accent2)', fontFamily: 'var(--mono)' }}>{result.duration}</span>
          </div>
          {result.columns && result.rows ? (
            <div style={{ overflowX: 'auto' }}>
              <table className="data-table">
                <thead><tr>{result.columns.map(c => <th key={c}>{c}</th>)}</tr></thead>
                <tbody>
                  {result.rows.map((row, i) => (
                    <tr key={i}>{row.map((v, j) => (
                      <td key={j} style={{ fontFamily: typeof v === 'number' ? 'var(--mono)' : undefined }}>
                        {v == null ? <span style={{ color: 'var(--muted)' }}>NULL</span> : String(v)}
                      </td>
                    ))}</tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="success">✓ {result.message}</div>
          )}
        </div>
      )}
    </>
  );
}

// ─── AI Query ─────────────────────────────────────────────────────────────────
function AIQuery() {
  const [input, setInput] = useState('');
  const [trans, setTrans] = useState(null);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const examples = [
    'Show all clients from Cairo',
    'Count customers in Alexandria',
    'Top 5 richest clients',
    'Show female clients',
    'Total balance in Assiut',
    'Show savings accounts',
    'Average balance by city',
    'Show clients with balance greater than 400000',
  ];

  const run = async () => {
    if (!input.trim()) return;
    setLoading(true); setError(''); setTrans(null); setResult(null);
    try {
      const r = await api.aiQuery(input);
      setTrans(r.translation);
      if (r.result) setResult(r.result);
      if (r.error) setError(r.error);
    } catch (e) { setError(e.message); }
    setLoading(false);
  };

  return (
    <>
      <div className="page-title">AI Query ✦ <span>Natural language → SQL</span></div>
      <div style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap' }}>
        {examples.map((e, i) => (
          <button key={i} onClick={() => setInput(e)} style={{ background: 'var(--surface2)', border: '1px solid var(--border)', color: 'var(--muted)', padding: '5px 12px', borderRadius: 20, cursor: 'pointer', fontSize: 12 }}>
            {e}
          </button>
        ))}
      </div>
      <div className="card mb16">
        <div className="ai-input-wrap">
          <input className="ai-input" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && run()} placeholder='Type in plain English, e.g. "Show all clients from Cairo with balance above 50000"' />
          <button className="ai-btn" onClick={run} disabled={loading}>{loading ? '…' : '✦ Translate & Run'}</button>
        </div>
        {trans && (
          <>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
              <div style={{ fontSize: 12, color: 'var(--muted)' }}>Generated SQL</div>
              <div style={{ fontSize: 12 }}>
                <span style={{ color: 'var(--muted)' }}>Confidence: </span>
                <span style={{ color: trans.confidence >= 0.9 ? 'var(--green)' : 'var(--amber)', fontWeight: 600 }}>{Math.round(trans.confidence * 100)}%</span>
              </div>
            </div>
            {trans.sql ? (
              <div className="sql-preview">{trans.sql}</div>
            ) : (
              <div className="error">{trans.explanation}</div>
            )}
            <div className="confidence-bar"><div className="confidence-fill" style={{ width: `${trans.confidence * 100}%` }} /></div>
            <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 6 }}>{trans.explanation}</div>
          </>
        )}
      </div>

      {error && <div className="error mb16">{error}</div>}

      {result && (
        <div className="card">
          <div className="card-title">{result.rows?.length ?? result.affected ?? 0} row(s) — {result.duration}</div>
          {result.columns && result.rows ? (
            <div style={{ overflowX: 'auto' }}>
              <table className="data-table">
                <thead><tr>{result.columns.map(c => <th key={c}>{c}</th>)}</tr></thead>
                <tbody>
                  {result.rows.map((row, i) => (
                    <tr key={i}>{row.map((v, j) => <td key={j}>{v == null ? '—' : String(v)}</td>)}</tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="success">✓ {result.message}</div>
          )}
        </div>
      )}
    </>
  );
}

// ─── Data Browser ─────────────────────────────────────────────────────────────
function DataBrowser() {
  const [tab, setTab] = useState('browse');
  const [clients, setClients] = useState([]);
  const [total, setTotal] = useState(0);
  const [city, setCity] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(0);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({ name: '', national_id: '', phone: '', email: '', gender: 'Male', birth_date: '1990-01-01', city: 'Cairo', address: '', account_type: 'Savings', balance: 0 });
  const [msg, setMsg] = useState('');

  const limit = 20;

  const load = useCallback(async () => {
    setLoading(true);
    const r = await api.getClients({ city, search, limit, offset: page * limit });
    setClients(r.data?.rows || []);
    setTotal(r.total || 0);
    setLoading(false);
  }, [city, search, page]);

  useEffect(() => { if (tab === 'browse') load(); }, [load, tab]);

  const del = async (id) => { if (!window.confirm(`Delete client #${id}?`)) return; await api.deleteClient(id); load(); };

  const submit = async () => {
    setMsg('');
    const r = await api.createClient({ ...form, balance: parseFloat(form.balance) || 0 });
    if (r.error) setMsg('Error: ' + r.error);
    else { setMsg('✓ Client created successfully'); load(); setTab('browse'); }
  };

  const cols = ['id', 'name', 'national_id', 'phone', 'email', 'gender', 'birth_date', 'city', 'address', 'account_type', 'balance', 'created_at'];

  return (
    <>
      <div className="page-title">Data Browser <span>{fmt(total)} total records</span></div>
      <div className="tabs">
        {[['browse', 'Browse'], ['insert', 'Add Client']].map(([k, l]) => (
          <div key={k} className={`tab ${tab === k ? 'active' : ''}`} onClick={() => setTab(k)}>{l}</div>
        ))}
      </div>

      {tab === 'browse' && (
        <>
          <div style={{ display: 'flex', gap: 10, marginBottom: 16 }}>
            <select value={city} onChange={e => { setCity(e.target.value); setPage(0); }} style={{ background: 'var(--surface2)', border: '1px solid var(--border)', color: 'var(--text)', padding: '8px 12px', borderRadius: 8, fontSize: 13, outline: 'none' }}>
              <option value="">All Cities</option>
              {['Cairo', 'Alexandria', 'Assiut', 'Luxor'].map(c => <option key={c}>{c}</option>)}
            </select>
            <input placeholder="Search by name or email..." value={search} onChange={e => { setSearch(e.target.value); setPage(0); }} style={{ flex: 1, background: 'var(--surface2)', border: '1px solid var(--border)', color: 'var(--text)', padding: '8px 12px', borderRadius: 8, fontSize: 13, outline: 'none' }} />
            <button className="run-btn" onClick={load}>Search</button>
          </div>
          <div className="card">
            {loading ? <div className="empty">Loading...</div> : (
              <div style={{ overflowX: 'auto' }}>
                <table className="data-table">
                  <thead><tr>
                    <th>ID</th><th>Name</th><th>City</th><th>Gender</th><th>Account</th><th>Balance</th><th>Created</th><th></th>
                  </tr></thead>
                  <tbody>
                    {clients.map((row, i) => (
                      <tr key={i}>
                        <td style={{ fontFamily: 'var(--mono)', color: 'var(--muted)' }}>{row[0]}</td>
                        <td style={{ fontWeight: 500 }}>{row[1]}</td>
                        <td><span style={{ background: `${CITY_COLORS[row[7]]}20`, color: CITY_COLORS[row[7]], padding: '2px 8px', borderRadius: 4, fontSize: 11, fontWeight: 600 }}>{row[7]}</span></td>
                        <td>{row[5]}</td>
                        <td style={{ fontSize: 11 }}>{row[9]}</td>
                        <td style={{ fontFamily: 'var(--mono)', color: 'var(--green)' }}>${fmt(row[10])}</td>
                        <td style={{ color: 'var(--muted)', fontSize: 12 }}>{row[11]}</td>
                        <td><button onClick={() => del(row[0])} style={{ background: 'transparent', border: 'none', color: 'var(--red)', cursor: 'pointer', fontSize: 14 }}>✕</button></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 12, fontSize: 13, color: 'var(--muted)' }}>
              <span>Page {page + 1} of {Math.ceil(total / limit)}</span>
              <div style={{ display: 'flex', gap: 8 }}>
                <button onClick={() => setPage(p => Math.max(0, p - 1))} disabled={page === 0} className="run-btn">←</button>
                <button onClick={() => setPage(p => p + 1)} disabled={(page + 1) * limit >= total} className="run-btn">→</button>
              </div>
            </div>
          </div>
        </>
      )}

      {tab === 'insert' && (
        <div className="card">
          <div className="card-title">Add New Client</div>
          <div className="form-row">
            {[['name', 'Full Name'], ['national_id', 'National ID'], ['phone', 'Phone'], ['email', 'Email'], ['address', 'Address']].map(([k, l]) => (
              <div key={k} className="form-field">
                <label>{l}</label>
                <input value={form[k]} onChange={e => setForm(f => ({ ...f, [k]: e.target.value }))} />
              </div>
            ))}
            <div className="form-field">
              <label>Birth Date</label>
              <input type="date" value={form.birth_date} onChange={e => setForm(f => ({ ...f, birth_date: e.target.value }))} />
            </div>
            <div className="form-field">
              <label>Gender</label>
              <select value={form.gender} onChange={e => setForm(f => ({ ...f, gender: e.target.value }))}>
                <option>Male</option><option>Female</option>
              </select>
            </div>
            <div className="form-field">
              <label>City (Shard)</label>
              <select value={form.city} onChange={e => setForm(f => ({ ...f, city: e.target.value }))}>
                {['Cairo', 'Alexandria', 'Assiut', 'Luxor'].map(c => <option key={c}>{c}</option>)}
              </select>
            </div>
            <div className="form-field">
              <label>Account Type</label>
              <select value={form.account_type} onChange={e => setForm(f => ({ ...f, account_type: e.target.value }))}>
                {['Savings', 'Current', 'Fixed Deposit', 'Business'].map(t => <option key={t}>{t}</option>)}
              </select>
            </div>
            <div className="form-field">
              <label>Balance (EGP)</label>
              <input type="number" value={form.balance} onChange={e => setForm(f => ({ ...f, balance: e.target.value }))} />
            </div>
          </div>
          <button className="submit-btn" onClick={submit}>✓ Insert Client (via Master)</button>
          {msg && <div className={msg.startsWith('✓') ? 'success mt16' : 'error mt16'}>{msg}</div>}
        </div>
      )}
    </>
  );
}

// ─── Replication ──────────────────────────────────────────────────────────────
function ReplicationView() {
  const [logs, setLogs] = useState([]);
  const load = async () => { const r = await api.replLog(); setLogs(r.logs || []); };

  useEffect(() => { load(); const id = setInterval(load, 4000); return () => clearInterval(id); }, []);

  const statusColor = s => s === 'success' ? 'var(--green)' : s === 'failed' ? 'var(--red)' : 'var(--amber)';

  return (
    <>
      <div className="page-title">Replication Log <span>Master → Worker sync</span></div>
      <div style={{ display: 'flex', gap: 12, marginBottom: 16 }}>
        {[['Goroutines', '3 parallel replicators', '⚡'], ['Channel', 'Buffered (cap 100)', '⇄'], ['Strategy', 'Broadcast all', '◈']].map(([t, d, i]) => (
          <div key={t} className="card" style={{ flex: 1 }}>
            <div style={{ fontSize: 24, marginBottom: 6 }}>{i}</div>
            <div style={{ fontWeight: 600 }}>{t}</div>
            <div style={{ fontSize: 12, color: 'var(--muted)' }}>{d}</div>
          </div>
        ))}
      </div>
      <div className="card">
        <div className="card-title">Recent Replication Events</div>
        {logs.length === 0 ? <div className="empty">No replication events yet. Try inserting a record.</div> :
          logs.map((l, i) => (
            <div key={i} className="log-line">
              <span className="log-time">{l.created_at}</span>
              <span style={{ color: 'var(--accent2)', width: 80, flexShrink: 0 }}>{l.op}</span>
              <span style={{ color: statusColor(l.status), width: 70, flexShrink: 0, fontWeight: 600 }}>{l.status}</span>
              <span style={{ flex: 1, color: 'var(--muted)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{l.sql_stmt}</span>
            </div>
          ))
        }
      </div>
    </>
  );
}

// ─── Leader Election ──────────────────────────────────────────────────────────
function ElectionView() {
  const [status, setStatus] = useState(null);
  const [events, setEvents] = useState([]);
  const [msg, setMsg] = useState('');

  const load = async () => {
    const r = await api.electionStatus();
    setStatus(r.status);
    setEvents(r.events || []);
  };
  useEffect(() => { load(); const id = setInterval(load, 5000); return () => clearInterval(id); }, []);

  const trigger = async () => { await api.triggerElection(); setMsg('Election triggered!'); load(); };
  const failover = async (node) => { await api.triggerFailover(node); setMsg(`Failover to ${node} complete`); load(); };

  return (
    <>
      <div className="page-title">Leader Election ♛ <span>Bully Algorithm</span></div>

      {status && (
        <div className="election-card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
            <div>
              <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 4 }}>Current Leader</div>
              <div className="leader-name">{status.leader_id}</div>
              <div style={{ display: 'flex', gap: 8, marginTop: 8 }}>
                <span className="term-badge">Term #{status.term}</span>
                <span style={{ background: 'rgba(16,185,129,0.15)', color: 'var(--green)', padding: '4px 12px', borderRadius: 20, fontSize: 12, fontWeight: 600 }}>{status.state?.toUpperCase()}</span>
              </div>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              <button className="danger-btn" onClick={trigger}>⚡ Trigger Election</button>
              {['worker-1', 'worker-2', 'worker-3'].map(n => (
                <button key={n} className="danger-btn" onClick={() => failover(n)}>Failover → {n}</button>
              ))}
            </div>
          </div>
        </div>
      )}

      {msg && <div className="success mb16">{msg}</div>}

      <div className="card">
        <div className="card-title">Algorithm: Bully</div>
        <div style={{ fontSize: 13, color: 'var(--muted)', lineHeight: 1.8 }}>
          Priority order: <strong style={{ color: 'var(--text)' }}>master-1 &gt; worker-3 &gt; worker-2 &gt; worker-1</strong><br />
          When master goes offline → highest-priority alive node wins the election → all other nodes are notified → new master takes over write operations.
        </div>
      </div>

      <div className="card mt16">
        <div className="card-title">Election History</div>
        {events.length === 0 ? <div className="empty">No election events yet.</div> :
          events.slice().reverse().map((e, i) => (
            <div key={i} className="log-line">
              <span className="log-time">{new Date(e.time).toLocaleTimeString()}</span>
              <span className="log-info" style={{ width: 160 }}>{e.event}</span>
              <span style={{ color: 'var(--text)' }}>{e.node_id}</span>
              <span style={{ marginLeft: 'auto', color: 'var(--muted)' }}>term #{e.term}</span>
            </div>
          ))
        }
      </div>
    </>
  );
}
